-- Migration 481: AA-1154 (A0, the CIS admin assistant: evidence, action catalogue and playbooks, no LLM) — the
-- assistant's windows, triggers and limits as settings.
--
-- Why. Tech lead decisions AI1-AI12 (S285 advisory, root docs/audits/2026-11-19-S285-session/advisory-ai-assistants.md):
-- one assistant inside the CIS admin turns the evidence of a Needs-attention item or an incident into ranked action
-- cards by rule (risk R0-R4, sourced predictions, way back). A0 has no LLM and no table: the cards are computed on read
-- from existing sources (api/services/ops_assist/). Every window, trigger, floor and cap the rules use is a setting
-- (tech lead S279), never a code literal.
--
-- What:
--   1. Twelve rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR), app cis, area "ops", scope platform, impact low,
--      maker-checker, no evidence, no env override, enforced (shared/ops_assist_settings.py names every key, the
--      settings-lint reader check). Defaults are the S285 advisory values (the throttle trigger and the spike
--      floor have their own keys, with the defaults of the refusal trigger and the R1 money cap they were split from):
--        cis.ops.assist_evidence_window_min    int minutes 5-240, default 30 (ledger + job failures read back)
--        cis.ops.assist_changes_window_min     int minutes 15-1440, default 120 ("what changed": ops events, routes)
--        cis.ops.assist_refused_trigger_calls  int calls 1-1000, default 3 (account-level refusals that open a signal)
--        cis.ops.assist_throttled_trigger_calls int calls 1-1000, default 3 (throttled calls that open a signal)
--        cis.ops.assist_spend_spike_factor     numeric x 1.5-20, default 3 (spend per hour vs the usual hourly median)
--        cis.ops.assist_spend_baseline_days    int days 1-30, default 7 (the days of that usual hourly median)
--        cis.ops.assist_spend_spike_floor_usd_h usd per hour 0-10, default 0.10 (no spike signal at or below it)
--        cis.ops.assist_wide_scope_stages      int stages 1-100, default 5 (an action that wide is R3)
--        cis.ops.assist_small_money_usd        usd 0-10, default 0.10 (the most an R1 action may cost)
--        cis.ops.assist_history_min_n          int outcomes 3-100, default 5 ("right k of n" shown from n)
--        cis.ops.assist_card_ttl_min           int minutes 5-240, default 30 (cards lock after it)
--        cis.ops.assist_reason_min_chars       int characters 10-500, default 20 (tech lead AI7)
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. Register 481.
--
-- Behaviour on apply. None for running code: no value row is seeded and the code on main reads none of the keys. After
-- the code PR the assistant reads the defaults until an administrator changes them.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: this migration-only PR first, applied on Dev by Infra Migration Apply when the job tables are idle (ADR 0017a),
-- then the code PR (no readiness raise: the reader falls back to the compiled default). DM-6.1: no personal data.
-- DM-7.1: no new table.
--
-- Number. Owner main max (480) + 1. If the owner main max + 1
-- differs at merge, renumber (git grep '481_' and '481' here, in tests/integration/test_aa1154_migration_481.py,
-- compiled_defaults.json's _generated line and docs/implementation-notes/AA-1154.md).
--
-- Locks. One INSERT ... ON CONFLICT of twelve rows (the definition guard trigger allows the file's role, cis_owner).
-- lock_timeout 5s. Re-runnable: ON CONFLICT DO NOTHING keeps a row an earlier run wrote.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the twelve keys' value rows first, then the
-- keys.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.ops.assist_evidence_window_min", "app": "cis", "area": "ops", "label": "Assistant: evidence window (minutes)", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) the evidence collector reads the AI gateway ledger (shared.llm_call_log: refused calls and spend per connection) and the failed jobs of this many minutes before now. The S285 advisory reads 30 minutes. Default 30.", "value_type": "int", "unit": "minutes", "min_value": 5, "max_value": 240, "allowed_values": null, "default_value": 30, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many minutes of recent AI calls and job failures the assistant reads as evidence.", "raise": "More calls in the sample and steadier numbers, but an old problem that already ended can still look open.", "lower": "Only the latest minutes count, so a short burst decides the cards; small samples give rougher numbers.", "when": "Raise it when the platform is quiet and few calls happen; lower it during a busy wave.", "example": "With the default 30, a card at 10:30 counts the refused calls made since 10:00."}, "vi": {"what": "Số phút gần nhất mà trợ lý đọc lời gọi AI và job lỗi để làm bằng chứng.", "raise": "Mẫu nhiều lời gọi hơn và số ổn định hơn, nhưng một lỗi đã hết vẫn có thể trông như đang mở.", "lower": "Chỉ tính những phút mới nhất, một đợt lỗi ngắn quyết định thẻ; mẫu nhỏ cho số thô hơn.", "when": "Tăng khi hệ thống vắng và ít lời gọi; giảm khi đang chạy wave đông.", "example": "Với mặc định 30, thẻ lúc 10:30 đếm các lời gọi bị từ chối từ 10:00."}}},
{"key": "cis.ops.assist_changes_window_min", "app": "cis", "area": "ops", "label": "Assistant: what changed window (minutes)", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) the \"what changed\" evidence lists the ops events (deploys, failed rollouts, alarms, service drops in acp_shared.ops_event) and the AI route versions saved in this many minutes before now. The S285 advisory reads 2 hours. Default 120.", "value_type": "int", "unit": "minutes", "min_value": 15, "max_value": 1440, "allowed_values": null, "default_value": 120, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How far back the assistant looks for recent changes: deploys, alarms and AI route versions.", "raise": "A slower cause (a deploy hours ago) still shows, but the list gets longer.", "lower": "A shorter list of the latest changes; an older cause may be missed.", "when": "Raise it when problems appear long after a change; lower it if the list is too long to read.", "example": "With the default 120, at 10:30 the list shows changes since 08:30."}, "vi": {"what": "Trợ lý nhìn lại bao xa để tìm thay đổi gần đây: deploy, cảnh báo và phiên bản route AI.", "raise": "Nguyên nhân chậm (deploy vài giờ trước) vẫn hiện, nhưng danh sách dài hơn.", "lower": "Danh sách ngắn gồm thay đổi mới nhất; nguyên nhân cũ hơn có thể bị bỏ sót.", "when": "Tăng khi lỗi xuất hiện lâu sau một thay đổi; giảm nếu danh sách quá dài để đọc.", "example": "Với mặc định 120, lúc 10:30 danh sách hiện thay đổi từ 08:30."}}},
{"key": "cis.ops.assist_refused_trigger_calls", "app": "cis", "area": "ops", "label": "Assistant: refused calls that open an AI access signal", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an AI connection whose calls were refused at account level (error class access_denied, credential or quota_exhausted) at least this many times inside the evidence window opens an \"AI access refused\" signal with its action cards, even before its connection circuit opens. An open connection circuit always opens the signal. Default 3.", "value_type": "int", "unit": "calls", "min_value": 1, "max_value": 1000, "allowed_values": null, "default_value": 3, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many account-level refusals on one AI connection make the assistant raise a signal before the circuit breaker does.", "raise": "Fewer early signals, but a refused account is noticed later.", "lower": "Earlier signals, but a single refused model may raise one that is not an account problem.", "when": "Lower it when the platform calls little and every refusal matters; raise it if one refused model keeps raising signals.", "example": "With the default 3, three refused calls on one connection in the window raise the signal."}, "vi": {"what": "Số lần bị từ chối ở cấp tài khoản trên một kết nối AI để trợ lý báo trước khi circuit breaker mở.", "raise": "Ít báo sớm hơn, nhưng tài khoản bị từ chối được phát hiện muộn hơn.", "lower": "Báo sớm hơn, nhưng một model bị từ chối riêng lẻ cũng có thể gây báo nhầm.", "when": "Giảm khi hệ thống ít gọi và lần từ chối nào cũng quan trọng; tăng nếu một model bị từ chối cứ gây báo.", "example": "Với mặc định 3, ba lời gọi bị từ chối trên một kết nối trong cửa sổ sẽ mở tín hiệu."}}},
{"key": "cis.ops.assist_throttled_trigger_calls", "app": "cis", "area": "ops", "label": "Assistant: throttled calls that open a throttle signal", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an AI connection with at least this many throttled calls (error class throttled) inside the evidence window opens an \"AI connection throttled\" signal with its action cards, even before its connection circuit opens. A circuit open on throttling always opens the signal. Separate from the refused-calls trigger, so quieting one never quiets the other. Default 3.", "value_type": "int", "unit": "calls", "min_value": 1, "max_value": 1000, "allowed_values": null, "default_value": 3, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many throttled calls on one AI connection make the assistant raise a throttle signal.", "raise": "Fewer throttle signals; a short burst of throttling stays quiet.", "lower": "Earlier throttle signals, including brief bursts that the limiter already absorbs.", "when": "Raise it during busy waves when some throttling is normal; lower it when calls are few and any throttle matters.", "example": "With the default 3, three throttled calls on one connection in the window raise the signal."}, "vi": {"what": "Số lời gọi bị giới hạn tốc độ (throttled) trên một kết nối AI để trợ lý báo tín hiệu throttle.", "raise": "Ít tín hiệu throttle hơn; một đợt throttle ngắn không gây báo.", "lower": "Báo throttle sớm hơn, kể cả đợt ngắn mà bộ giới hạn đã tự xử lý.", "when": "Tăng khi wave đông và throttle là bình thường; giảm khi ít lời gọi và lần throttle nào cũng quan trọng.", "example": "Với mặc định 3, ba lời gọi bị throttle trên một kết nối trong cửa sổ sẽ mở tín hiệu."}}},
{"key": "cis.ops.assist_spend_spike_factor", "app": "cis", "area": "ops", "label": "Assistant: AI spend spike factor", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an AI connection whose spend per hour inside the evidence window is at least this many times its usual hourly spend (the median over cis.ops.assist_spend_baseline_days days) and above cis.ops.assist_spend_spike_floor_usd_h opens an \"AI spend spike\" signal. The same median is the baseline of the \"if we do nothing\" cost on every AI card. Default 3.", "value_type": "numeric", "unit": "x", "min_value": 1.5, "max_value": 20, "allowed_values": null, "default_value": 3, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many times its usual hourly spend an AI connection must reach before the assistant calls it a spend spike.", "raise": "Only big jumps raise a signal; a slow rise goes unnoticed longer.", "lower": "Smaller jumps raise a signal, including normal busy hours of a wave.", "when": "Raise it while waves run often; lower it when spend is flat and any jump is suspect.", "example": "With the default 3, a connection that usually spends 0.20 USD an hour raises a signal at 0.60 USD an hour."}, "vi": {"what": "Chi phí theo giờ của một kết nối AI phải gấp bao nhiêu lần mức thường ngày để trợ lý coi là tăng đột biến.", "raise": "Chỉ bước nhảy lớn mới báo; tăng chậm bị bỏ qua lâu hơn.", "lower": "Bước nhảy nhỏ cũng báo, kể cả giờ bận bình thường của một wave.", "when": "Tăng khi wave chạy thường xuyên; giảm khi chi phí đều và bước nhảy nào cũng đáng ngờ.", "example": "Với mặc định 3, kết nối thường tốn 0,20 USD một giờ sẽ báo khi lên 0,60 USD một giờ."}}},
{"key": "cis.ops.assist_spend_baseline_days", "app": "cis", "area": "ops", "label": "Assistant: days of usual AI spend", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) the usual spend of an AI connection is its median hourly spend over this many days before the evidence window (hours with no call count as 0). The spend spike signal compares the spend per hour of the window with it, and it is the baseline of the \"if we do nothing\" cost on every AI card. The S285 advisory reads 7 days. Default 7.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 30, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days of past AI spend the assistant uses to know a connection's usual hourly spend.", "raise": "A steadier usual spend that a few busy days do not move, but a lasting change in use is learned slower.", "lower": "The usual spend follows recent use sooner, and a busy day can hide a spike that follows it.", "when": "Keep a full week so weekdays and weekends both count; lower it after a lasting change in how much AI the platform uses.", "example": "With the default 7, a card on 24/11 compares with the median hour from 17/11 to 24/11."}, "vi": {"what": "Số ngày chi phí AI trước đó mà trợ lý dùng để biết mức chi theo giờ thường ngày của một kết nối.", "raise": "Mức thường ngày ổn định hơn, vài ngày bận không làm lệch, nhưng thay đổi lâu dài được học chậm hơn.", "lower": "Mức thường ngày theo sát mức dùng gần đây hơn, và một ngày bận có thể che một đợt tăng ngay sau đó.", "when": "Giữ trọn một tuần để tính cả ngày thường và cuối tuần; giảm sau khi mức dùng AI của hệ thống đổi hẳn.", "example": "Với mặc định 7, thẻ ngày 24/11 so với giờ trung vị từ 17/11 tới 24/11."}}},
{"key": "cis.ops.assist_spend_spike_floor_usd_h", "app": "cis", "area": "ops", "label": "Assistant: smallest AI spend per hour that can be a spike", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an AI connection spending at most this many USD per hour inside the evidence window never opens an \"AI spend spike\" signal, whatever its usual spend, so a connection with almost no usual spend does not raise one on its first cents. Separate from the most an R1 action may cost. Default 0.10 USD per hour.", "value_type": "usd", "unit": "USD/hour", "min_value": 0, "max_value": 10, "allowed_values": null, "default_value": 0.1, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The lowest spend per hour at which the assistant can call a connection's spend a spike.", "raise": "Small connections never raise a spike signal; only real money does.", "lower": "Even a few cents an hour can raise a spike on a connection that is usually idle.", "when": "Keep it near the hourly cost you would not act on; raise it if idle connections keep raising spikes.", "example": "With the default 0.10, a usually idle connection spending 0.05 USD an hour raises no signal."}, "vi": {"what": "Mức chi theo giờ thấp nhất mà trợ lý có thể coi chi phí của một kết nối là tăng đột biến.", "raise": "Kết nối nhỏ không bao giờ báo tăng đột biến; chỉ số tiền đáng kể mới báo.", "lower": "Chỉ vài cent một giờ cũng có thể gây báo trên một kết nối thường không dùng.", "when": "Giữ gần mức chi theo giờ mà bạn sẽ không xử lý; tăng nếu kết nối ít dùng cứ gây báo.", "example": "Với mặc định 0,10, kết nối thường không dùng chi 0,05 USD một giờ không gây báo."}}},
{"key": "cis.ops.assist_wide_scope_stages", "app": "cis", "area": "ops", "label": "Assistant: stages that make an action wide", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an action on an AI connection or route that serves at least this many active stages has a wide scope, which raises its risk to R3 (the scope axis of the risk rule: one job, one wave, one stage, one app, every app). Default 5.", "value_type": "int", "unit": "stages", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many AI stages an action must touch before the assistant treats it as wide and high risk (R3).", "raise": "Fewer actions count as high risk and fewer ask for a written reason.", "lower": "More actions count as high risk and ask for a written reason.", "when": "Lower it when most stages share one connection; raise it if small route changes keep showing as R3.", "example": "With the default 5, switching off a connection that serves 13 stages is R3."}, "vi": {"what": "Số stage AI mà một hành động phải chạm tới để trợ lý coi là phạm vi rộng và rủi ro cao (R3).", "raise": "Ít hành động bị coi là rủi ro cao và ít phải ghi lý do.", "lower": "Nhiều hành động bị coi là rủi ro cao và phải ghi lý do.", "when": "Giảm khi phần lớn stage dùng chung một kết nối; tăng nếu thay đổi route nhỏ cứ hiện R3.", "example": "Với mặc định 5, tắt một kết nối phục vụ 13 stage là R3."}}},
{"key": "cis.ops.assist_small_money_usd", "app": "cis", "area": "ops", "label": "Assistant: most an R1 action may cost", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an action whose estimated cost is at most this amount counts as \"0 USD or a few cents\" on the money axis of the risk rule (R1 at most); a higher or unknown paid cost raises it to R3. Default 0.10 USD.", "value_type": "usd", "unit": "USD", "min_value": 0, "max_value": 10, "allowed_values": null, "default_value": 0.1, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The most an action may cost and still count as low risk on money.", "raise": "More paid actions count as low risk and need no written reason.", "lower": "Even small paid actions count as high risk and ask for a reason.", "when": "Keep it near the cost of one connection probe run; lower it if the monthly AI cap is tight.", "example": "With the default 0.10 USD, a probe run estimated at 0.02 USD stays R1."}, "vi": {"what": "Mức chi tối đa của một hành động mà vẫn được coi là rủi ro thấp về tiền.", "raise": "Nhiều hành động tốn tiền hơn được coi là rủi ro thấp và không cần ghi lý do.", "lower": "Cả hành động tốn ít tiền cũng bị coi là rủi ro cao và phải ghi lý do.", "when": "Giữ gần chi phí một lượt probe kết nối; giảm nếu trần chi AI hằng tháng đang chặt.", "example": "Với mặc định 0,10 USD, một lượt probe ước 0,02 USD vẫn là R1."}}},
{"key": "cis.ops.assist_history_min_n", "app": "cis", "area": "ops", "label": "Assistant: outcomes needed before a history confidence", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) a prediction shows its history confidence (\"right k of n\") only once this action type has at least this many measured outcomes; below it the card says \"not enough data\". The S285 advisory sets 5. Default 5.", "value_type": "int", "unit": "outcomes", "min_value": 3, "max_value": 100, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many measured results an action type needs before its cards show \"right k of n times\".", "raise": "The history number appears later but means more.", "lower": "The history number appears sooner but may mislead with few results.", "when": "Keep the default until an action type has a few months of results.", "example": "With the default 5, an action with 4 measured results still shows \"not enough data\"."}, "vi": {"what": "Số kết quả đã đo mà một loại hành động cần trước khi thẻ hiện \"đúng k trên n lần\".", "raise": "Con số lịch sử hiện muộn hơn nhưng đáng tin hơn.", "lower": "Con số lịch sử hiện sớm hơn nhưng có thể gây hiểu nhầm khi ít kết quả.", "when": "Giữ mặc định cho tới khi một loại hành động có vài tháng kết quả.", "example": "Với mặc định 5, hành động có 4 kết quả đã đo vẫn hiện \"chưa đủ dữ liệu\"."}}},
{"key": "cis.ops.assist_card_ttl_min", "app": "cis", "area": "ops", "label": "Assistant: card lifetime (minutes)", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) a set of action cards is valid for this many minutes after its evidence was read; afterwards the panel locks it and asks to analyse again, so nobody acts on stale evidence. The S285 advisory sets 30 minutes. Default 30.", "value_type": "int", "unit": "minutes", "min_value": 5, "max_value": 240, "allowed_values": null, "default_value": 30, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How long a set of action cards stays usable before the page asks to read the evidence again.", "raise": "Cards stay usable longer, with a higher chance the situation already changed.", "lower": "Cards expire sooner and the evidence is read again more often.", "when": "Lower it during a fast-moving incident; raise it for slow problems such as a cost drift.", "example": "With the default 30, cards read at 10:02 expire at 10:32."}, "vi": {"what": "Bộ thẻ hành động dùng được bao lâu trước khi trang yêu cầu đọc lại bằng chứng.", "raise": "Thẻ dùng được lâu hơn, nhưng dễ tình hình đã đổi.", "lower": "Thẻ hết hạn sớm hơn và bằng chứng được đọc lại thường hơn.", "when": "Giảm khi sự cố diễn biến nhanh; tăng cho vấn đề chậm như chi phí trôi dần.", "example": "Với mặc định 30, thẻ đọc lúc 10:02 hết hạn lúc 10:32."}}},
{"key": "cis.ops.assist_reason_min_chars", "app": "cis", "area": "ops", "label": "Assistant: shortest reason for an R3 card", "description": "On the CIS admin assistant (Ecosystem status page, Actions on a Needs-attention row; api/services/ops_assist/) an R3 card (loosens a limit, costs money, wide scope or hard to undo) asks the person who acts for a written reason of at least this many characters; the API the card calls keeps its own approval rule (tech lead decision AI7: no new approval layer). Default 20.", "value_type": "int", "unit": "characters", "min_value": 10, "max_value": 500, "allowed_values": null, "default_value": 20, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The shortest written reason a high-risk (R3) action card asks for before its action is taken.", "raise": "Longer reasons, better records, a little slower in an incident.", "lower": "Faster to act, with thinner records of why.", "when": "Keep the tech lead's 20 unless audits show reasons that say too little.", "example": "With the default 20, \"provider refused, testing\" (25 characters) is accepted."}, "vi": {"what": "Độ dài tối thiểu của lý do viết tay mà thẻ rủi ro cao (R3) yêu cầu trước khi thực hiện.", "raise": "Lý do dài hơn, hồ sơ rõ hơn, chậm hơn một chút khi có sự cố.", "lower": "Thực hiện nhanh hơn, hồ sơ lý do sơ sài hơn.", "when": "Giữ mức 20 của tech lead trừ khi audit thấy lý do quá sơ sài.", "example": "Với mặc định 20, \"provider refused, testing\" (25 ký tự) được chấp nhận."}}}
]
